// Unit tests for the configure-time build identifiers (see AGENTS.md's
// build number policy: "a release must never ship without build
// identifiers present"). The header is generated by CMakeLists.txt's
// configure_file() from src/version.hpp.in, so this validates the stamping
// mechanism end to end — a build without version.hpp.in wired up fails to
// compile this test at all.

#include <iostream>
#include <string>

#include "keepsake/version.hpp"

namespace {

int g_failures = 0;

#define CHECK(expr)                                                            \
    do {                                                                       \
        if (!(expr)) {                                                         \
            std::cerr << "FAILED: " << #expr                                   \
                      << " at version_test.cpp:" << __LINE__ << "\n";           \
            ++g_failures;                                                      \
        }                                                                      \
    } while (0)

bool isSemver(const std::string &text) {
    if (text.size() < 5) return false;
    size_t dots = 0;
    for (char c : text) {
        if (c == '.') {
            ++dots;
        } else if (c < '0' || c > '9') {
            return false;
        }
    }
    // d+.d+.d+ — at least three components.
    return dots == 2;
}

bool isHexShortSha(const std::string &text) {
    if (text == "unknown") return true; // the documented degraded fallback
    if (text.size() != 6) return false;
    for (char c : text) {
        if (!((c >= '0' && c <= '9') || (c >= 'a' && c <= 'f'))) return false;
    }
    return true;
}

} // namespace

int main() {
    const std::string version{KEEPSAKE_VERSION};
    const std::string buildId{KEEPSAKE_BUILD_ID};

    // Both identifiers are present and non-empty — a bare or missing stamp
    // is exactly what AGENTS.md says may never ship.
    CHECK(!version.empty());
    CHECK(!buildId.empty());

    // The version is the CMake project() VERSION (x.y.z).
    CHECK(isSemver(version));

    // The build id is the 6-char short SHA, or the documented "unknown"
    // fallback when Git wasn't available at configure time.
    CHECK(isHexShortSha(buildId));

    std::cout << "version_test " << (g_failures ? "FAILED" : "OK")
              << " (keepsake " << version << ", build " << buildId << ")\n";
    return g_failures ? 1 : 0;
}
